db = json.load(open(DB, encoding="utf-8"))
idx = {e.get("serial"): e for e in db}

for serial, rec in REC.items():
    fp = os.path.join(DRAFTS, f"draft_{serial}.json")
    if not os.path.exists(fp):
        print("MISSING FILE", serial); continue
    d = json.load(open(fp, encoding="utf-8"))
    d["recommend"] = rec
    json.dump(d, open(fp, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
    # verify
    entry = idx.get(serial)
    ctx = dict(entry)
    ctx["recommend"] = rec
    for k in ("desc_cn", "silver_reason", "payor_model"):
        if d.get(k):
            ctx[k] = d[k]
    iss = C.validate(ctx, skip={"R10"})
    cl = C.content_len(rec)
    status = "PASS" if not iss else "FAIL:" + ";".join(iss)
    print(f"{serial} len={cl} {status}")
